import React, { useState } from "react";

const AddExpense = ({ addTransaction }) => {
  const [data, setData] = useState({
    title: "",
    amount: ""
  });

  const handleChange = (e) => {
    setData({
      ...data,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    addTransaction(data);
    setData({ title: "", amount: "" });
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        name="title"
        placeholder="Title"
        value={data.title}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      />
      <input
        name="amount"
        placeholder="Amount"
        value={data.amount}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
      />
      <button style={{
        width: "100%",
        padding: "10px",
        background: "#4CAF50",
        color: "white",
        border: "none",
        borderRadius: "5px"
      }}>
        Add Expense
      </button>
    </form>
  );
};

export default AddExpense;
